import java.io.*;
import java.util.*;

public class Main {
    static class Node { String val; Node left, right; Node(String v) { val = v; } }
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        if (line == null || line.trim().isEmpty()) { System.out.println(); return; }
        String[] tokens = line.trim().split("\\s+");
        if (tokens.length == 0 || tokens[0].equals("null")) { System.out.println(); return; }
        Node root = new Node(tokens[0]);
        ArrayDeque<Node> q = new ArrayDeque<>();
        q.add(root);
        int i = 1;
        while (!q.isEmpty() && i < tokens.length) {
            Node curr = q.poll();
            if (i < tokens.length && !tokens[i].equals("null")) {
                curr.left = new Node(tokens[i]);
                q.add(curr.left);
            }
            i++;
            if (i < tokens.length && !tokens[i].equals("null")) {
                curr.right = new Node(tokens[i]);
                q.add(curr.right);
            }
            i++;
        }
        List<List<String>> levels = new ArrayList<>();
        q.add(root);
        while (!q.isEmpty()) {
            int size = q.size();
            List<String> curLevel = new ArrayList<>();
            for (int k = 0; k < size; k++) {
                Node n = q.poll();
                curLevel.add(n.val);
                if (n.left != null) q.add(n.left);
                if (n.right != null) q.add(n.right);
            }
            levels.add(curLevel);
        }
        StringBuilder sb = new StringBuilder();
        boolean first = true;
        for (int k = levels.size() - 1; k >= 0; k--) {
            for (String val : levels.get(k)) {
                if (!first) sb.append(' ');
                sb.append(val);
                first = false;
            }
        }
        System.out.println(sb);
    }
}

