#include <queue>
#include <algorithm>
using namespace std;

struct Node { string val; Node *left = nullptr, *right = nullptr; Node(string v): val(v) {} };

int main() {
    vector<string> tokens; string s;
    while (cin >> s) tokens.push_back(s);
    if (tokens.empty() || tokens[0] == "null") { cout << "\n"; return 0; }
    Node* root = new Node(tokens[0]);
    queue<Node*> q;
    q.push(root);
    size_t i = 1;
    while (!q.empty() && i < tokens.size()) {
        Node* curr = q.front(); q.pop();
        if (i < tokens.size() && tokens[i] != "null") {
            curr->left = new Node(tokens[i]);
            q.push(curr->left);
        }
        i++;
        if (i < tokens.size() && tokens[i] != "null") {
            curr->right = new Node(tokens[i]);
            q.push(curr->right);
        }
        i++;
    }
    vector<vector<string>> levels;
    q.push(root);
    while (!q.empty()) {
        int sz = q.size();
        vector<string> cur;
        while (sz--) {
            Node* n = q.front(); q.pop();
            cur.push_back(n->val);
            if (n->left) q.push(n->left);
            if (n->right) q.push(n->right);
        }
        levels.push_back(cur);
    }
    reverse(levels.begin(), levels.end());
    bool first = true;
    for (auto& lvl : levels) {
        for (auto& v : lvl) {
            if (!first) cout << ' '; cout << v; first = false;
        }
    }
    cout << "\n";
    return 0;
}

