import sys
from collections import deque

class Node:
    def __init__(self, val):
        self.val = int(val)
        self.left = None
        self.right = None

def build_tree(tokens):
    if not tokens or tokens[0] == 'null': return None
    root = Node(tokens[0])
    q = deque([root])
    i = 1
    while q and i < len(tokens):
        curr = q.popleft()
        if i < len(tokens) and tokens[i] != 'null':
            curr.left = Node(tokens[i])
            q.append(curr.left)
        i += 1
        if i < len(tokens) and tokens[i] != 'null':
            curr.right = Node(tokens[i])
            q.append(curr.right)
        i += 1
    return root

def longest_path(node):
    if not node: return 0, 0
    if not node.left and not node.right:
        return 1, node.val
    if node.left and not node.right:
        l_len, l_sum = longest_path(node.left)
        return l_len + 1, l_sum + node.val
    if not node.left and node.right:
        r_len, r_sum = longest_path(node.right)
        return r_len + 1, r_sum + node.val
    l_len, l_sum = longest_path(node.left)
    r_len, r_sum = longest_path(node.right)
    if l_len > r_len:
        return l_len + 1, l_sum + node.val
    elif r_len > l_len:
        return r_len + 1, r_sum + node.val
    else:
        return l_len + 1, max(l_sum, r_sum) + node.val

def solve():
    tokens = sys.stdin.read().split()
    root = build_tree(tokens)
    if not root:
        print(0); return
    _, ans = longest_path(root)
    print(ans)

if __name__ == '__main__':
    solve()

