using namespace std;

struct DSU {
    vector<int> parent;
    DSU(int n) {
        parent.resize(n);
        for (int i = 0; i < n; i++) parent[i] = i;
    }
    int find(int i) {
        if (parent[i] == i) return i;
        return parent[i] = find(parent[i]);
    }
    bool unite(int u, int v) {
        int ru = find(u), rv = find(v);
        if (ru == rv) return false;
        parent[ru] = rv;
        return true;
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int n, e;
    if (!(cin >> n >> e)) return 0;
    if (e != n - 1) {
        cout << "false\n";
        return 0;
    }
    DSU dsu(n);
    for (int i = 0; i < e; i++) {
        int u, v;
        cin >> u >> v;
        if (!dsu.unite(u, v)) {
            cout << "false\n";
            return 0;
        }
    }
    cout << "true\n";
    return 0;
}

